insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('nix-geed-iwara-koids-sechzeenablech-und-a-frische-soeoewagwuuzlde-im-zoeoet', 'Nix geed iwara koids Sechzeenablech und a frische Sööwagwuuzlde im Zööt!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Nichts geht über ein kaltes Sechzehnerblech und ''ne frische Selbergewutzelte im Zelt!', '[{"kategorie": "wörtlich", "text": "\"Nichts geht über ''ne kalte Bierdose und ''ne frische Selbergewuzelte im Zelt!\"  2. Kaltes Dosenbier, und eine frische, von Hand gedrehte Zigarette – mehr brauch ich nicht im Zelt!  3. Bier aus der Dose und ’ne frisch Gedrehte – so schmeckt Freiheit im Zelt!"}]'::jsonb, ''),
  ('nix-geed-iwara-koids-sechzeenablech-und-a-frisch-gwuuzlde-im-zoeoet', 'Nix geed iwara koids Sechzeenablech und a frisch Gwuuzlde im Zööt!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Nichts geht über ein kaltes Sechzehnerblech und ''ne frisch Gewutzelte im Zelt!', '[{"kategorie": "wörtlich", "text": "\"Nichts geht über ''ne kalte Bierdose und ''ne frische Selbstgedrehte im Zelt!\"  2. Kaltes Dosenbier, und eine frische, von Hand gedrehte Zigarette – mehr brauch ich nicht im Zelt!  3. Bier aus der Dose und ’ne frisch Gedrehte – so schmeckt Freiheit im Zelt!"}]'::jsonb, 'a Gwuuzlde'),
  ('tschueue-amoi-i-bau-uns-dawaeu-an-entschbaunntn-soeoewagwuuzldn', 'Tschüü amoi - I bau uns dawäu an entschbaunntn Sööwagwuuzldn!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Chill mal, ich bau uns derweil ''nen entspannten Selbergewutzelten!', '[{"kategorie": "wörtlich", "text": "\"Chill mal - ich dreh uns derweil ''nen frischen Joint von Hand!\"  2. Bleib locker - ich roll uns derweil was Schönes von Hand!  3. Entspann dich, ich bau uns derweil ein goldenes Gerät von Hand!"}]'::jsonb, ''),
  ('tschueue-amoi-i-draa-uns-dawaeu-a-soeoewagwuuzlde-von-haund', 'Tschüü amoi - I draa uns dawäu a Sööwagwuuzlde von Haund!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Chill mal, ich dreh uns derweil ''ne Selbergewutzelte von Hand!', '[{"kategorie": "wörtlich", "text": "\"Chill mal - ich dreh uns derweil ''ne Selbstgerollte von Hand!\"  2. Bleib locker - ich roll uns derweil ''nen schönen Tschick von Hand!  3. Entspann dich, ich roll uns derweil ein Zigarettchen von Hand!"}]'::jsonb, ''),
  ('tschueue-amoi-i-draa-uns-dawaeu-a-frisch-gwuuzlde-von-haund', 'Tschüü amoi - I draa uns dawäu a frisch Gwuuzlde von Haund!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Chill mal, ich dreh uns derweil ''ne frisch Gewutzelte von Hand!', '[{"kategorie": "wörtlich", "text": "\"Chill mal - ich dreh uns derweil ''ne frische Selbstgerollte von Hand!\"  2. Bleib locker - ich roll uns derweil ''nen schönen, frischen Joint von Hand!  3. Entspann dich, ich bau uns derweil ein frisches Gerät von Hand!"}]'::jsonb, 'a Gwuuzlde'),
  ('gwuuzlde-nuudln', 'gwuuzlde Nuudln', '', '', '', 'Wiener Küche & Gaumenfreuden', 'gewutzelte Nudeln', '[{"kategorie": "wörtlich", "text": "\"handgerollte Nudeln\" (von \"gewutzelt\"=\"handgerollt\" und \"Nudeln\"=\"längliche Fingernudeln aus Kartoffelteig\")"}, {"kategorie": "Kulinarik", "text": "\"Wutzelnudeln\" (in Butterbröseln, Mohn oder Nüssen, etc. geschwenkte Kartoffelnudeln), [[Schupfnudeln]]"}]'::jsonb, 'Kumm zum Essn vuabei - I koch heit gwuuzlde Nuudln mit Sauakraut und Schbeck!'),
  ('kumm-zum-essn-vuabei-i-koch-heit-gwuuzlde-nuudln-mit-sauakraut-und-schbeck', 'Kumm zum Essn vuabei - I koch heit gwuuzlde Nuudln mit Sauakraut und Schbeck!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Komm zum Essen vorbei - ich koche heut gewutzelte Nudeln mit Sauerkraut und Speck!', '[{"kategorie": "wörtlich", "text": "\"Heut gibt''s bei mir handgerollte Kartoffelnudeln mit Sauerkraut und Speck - kommst du?\"  2. Willst du vorbeikommen? Ich mach'' Schupfnudel-Pfanne mit Kraut und durchwachsenem Speck!  3. Bei mir dampft heute die Pfanne: Selbstgerollte Nudeln mit herzhaftem Sauerkraut und knusprigem Speck. Willst du vorbeikommen?"}]'::jsonb, ''),
  ('aufn-grissbaam-kumman-bei-uns-imma-aa-siasse-zuckaln-im-wuuzlpapia', 'Aufn Grissbaam kumman bei uns imma aa siasse Zuckaln im Wuuzlpapia!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Auf den Christbaum kommen bei uns immer auch süße Zuckerln im Wutzelpapier!', '[{"kategorie": "wörtlich", "text": "\"Auf den Weihnachtsbaum kommen bei uns immer auch süße Bonbons im Wickelpapier!\"  2. Bei uns ist es Brauch, den Tannenbaum auch mit leckeren Bonbons in buntem Stanniolpapier zu behängen!  3. Bei uns hängen auch immer leckere Bonbons in Glitzerpapier am Christbaum!"}]'::jsonb, ''),
  ('oone-a-blaadl-is-da-gaunze-taabak-fian-oasch-host-no-a-wicklpapia', 'Oone a Blaadl is da gaunze Taabak fian Oasch - host no a Wicklpapia?', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Ohne Blättchen ist der ganze Tabak für''n Arsch - hast du noch Wickelpapier?', '[{"kategorie": "wörtlich", "text": "\"Ohne Papers ist der Tabak nutzlos – hast du noch Blättchen?\"  2. Wenn wir keine Blättchen haben, war''s das mit Rauchen – hast du noch Wickler?  3. Keine Tüten, kein Spaß. Hast du noch was zum Drehen?"}]'::jsonb, ''),
  ('oone-aan-gscheidn-wuuzlkopf-kaunnsd-de-tschik-glei-vergessn-brennd-ollas-schiif', 'Oone aan gscheidn Wuuzlkopf kaunnsd de Tschik glei vergessn - brennd ollas schiif!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Ohne ''nen g’scheiten Wutzelkopf kannst du die Tschick gleich vergessen – brennt alles schief!', '[{"kategorie": "wörtlich", "text": "\"Ohne ''nen g’scheiten Filtertip kannst du die Zigaretten gleich vergessen – brennt alles schief!\"  2. Eine schlecht gemachte Spitze ruiniert die ganze selbstgedrehte Zigarette!  3. Ohne saubere Filterspitze kannst du die Zigarette vergessen – da zieht sie schlecht und brennt schief!"}]'::jsonb, ''),
  ('den-kostn-daheebsd-allaanich-nii', 'Den Kostn daheebsd allaanich nii !', '', '', '', 'Wiener Sprüche, die sitzen!', 'Den Kasten derhebst du alleine nie!', '[{"kategorie": "wörtlich", "text": "\"Diesen Kasten bekommst du alleine nicht hochgehoben!\"  2. Den Kasten kannst du alleine nicht stemmen!  3. Alleine kriegst du diesen Kasten nie hoch!"}]'::jsonb, ''),
  ('drei-gschroppn-und-a-voizeithockn-des-daheebd-kaana-allaanich', 'Drei Gschroppn und a Voizeithockn - des daheebd kaana allaanich!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Drei G''schrappen und eine Vollzeithack''n - das derhebt keiner alleine!', '[{"kategorie": "wörtlich", "text": "\"Drei Kinder und ein Vollzeitjob - das schafft niemand alleine!\"  2. Drei Kinder und ein Vollzeitjob – das ist alleine kaum zu bewältigen!  3. Drei Kids und ein 40-Stunden-Job - das ist einfach zu viel für eine Person allein!"}]'::jsonb, ''),
  ('de-muadstrumm-buudn-dahaazd-mit-dem-klaanan-schdroola-nii', 'De muadstrumm Buudn dahaazd mit dem klaanan Schdroola nii!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Diese mordstrumm Bude derheizt du mit diesem kleinen Strahler nie!', '[{"kategorie": "wörtlich", "text": "\"Diese Riesenwohnung bekommst du mit so ''nem kleinen Strahler nie geheizt!\"  2. Mit so ''nem kleinen Heizstrahler lässt sich diese große Wohnung nicht ausreichend beheizen!  3. Diese Wohnung ist einfach zu groß, um sie mit einem so kleinen Strahler warm zu bekommen!"}]'::jsonb, ''),
  ('drei-palettn-doosnbia-daschlepp-i-grod-noo-so-allaanich', 'Drei Palettn Doosnbia daschlepp I grod noo so allaanich!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Drei Paletten Dosenbier derschleppe ich grad noch so alleine!', '[{"kategorie": "wörtlich", "text": "\"Drei Paletten Dosenbier kann ich gerade noch so alleine tragen!\"  2. Die drei Paletten krieg ich gerade noch alleine gewuchtet!  3. Drei Paletten Dosenbier krieg ich gerade noch aus eigener Kraft geschultert!"}]'::jsonb, ''),
  ('si-darappln', 'si darappln', '', '', '', 'Grundwortschatz Wienerisch', 'sich derrappeln', '[{"kategorie": "wörtlich", "text": "\"sich derrappeln\" (aus dem intensivierenden Präfix [[der-]]=\"er-\" und \"rappeln\"=\"rütteln\")"}, {"kategorie": "fig.", "text": "\"sich aufrappeln\", \"sich wieder auf die Beine stellen\", sich zurückkämpfen\", \"wieder auf die Beine kommen\", \"die Kurve kriegen\", \"Tritt fassen\", \"sich von etwas erholen\" (Krankheit, Schreck, etc.), [[sich derfangen]]"}]'::jsonb, 'Noch da Kraunkheid hoda si nii wiida so richtig darappld!'),
  ('noch-da-kraunkheid-hoda-si-nii-wiida-so-richtig-darappld', 'Noch da Kraunkheid hoda si nii wiida so richtig darappld!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Nach der Krankheit hat er sich nie wieder so richtig derrappelt!', '[{"kategorie": "wörtlich", "text": "\"Nach der Krankheit ist er nie wieder so richtig genesen!\"  2. Nach dieser Krankheit ist er nie wieder so richtig auf die Beine gekommen!  3. Nach dieser Krankheit hat er sich nie wieder so richtig erfangen!"}]'::jsonb, ''),
  ('waunnsd-so-tiaf-in-da-scheisse-schdecksd-wiar-i-darapplsd-di-a-leebtooch-nimma', 'Waunnsd so tiaf in da Scheisse schdecksd wiar I, darapplsd di a Leebtooch nimma!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wenn du so tief in der Scheiße steckst wie ich, derrappelst du dich ein Lebtag nimmer!', '[{"kategorie": "wörtlich", "text": "\"Wenn du so tief in der Scheiße steckst wie ich, kommst du nie wieder so richtig auf die Beine!\"  2. Wenn du einmal so am Boden bist wie ich, wirst du ein Leben lang nicht mehr richtig Tritt fassen!  3. Wenn du einmal so tief drin hängst wie ich, kommst du aus dem Loch nie wieder raus!"}]'::jsonb, 'si darappln'),
  ('ea-hod-de-sauteire-vaasn-vom-tisch-gschdessn-owa-daunn-im-foin-grod-noo-dafaungan', 'Ea hod de sauteire Vaasn vom Tisch gschdessn, owa daunn im Foin grod noo dafaungan!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Er hat die sauteure Vase vom Tisch gestoßen, aber dann im Fallen gerade noch derfangen!', '[{"kategorie": "wörtlich", "text": "\"Er stieß die teure Vase vom Tisch, konnte sie aber im letzten Moment noch auffangen!\"  2. \"Ein Stoß, ein Fall – aber er hat die sauteure Vase gerade noch rechtzeitig aufgefangen!\"  3. \"Die sündteure Vase war schon unterwegs nach unten, doch er hat sie kurz vor dem Aufprall noch aus der Luft gefischt!\""}]'::jsonb, ''),
  ('si-dafaungan', 'si dafaungan', '', '', '', 'Grundwortschatz Wienerisch', 'sich derfangen', '[{"kategorie": "wörtlich", "text": "\"sich derfangen\" (aus dem intensivierenden Präfix [[der-]]=\"er-\" und \"sich fangen\"=\"sich sammeln\")"}, {"kategorie": "fig.", "text": "\"sich erfangen\", \"wieder auf die Beine kommen\", \"Tritt fassen\", \"wieder ins Gleichgewicht kommen\", \"sich stabilisieren\", \"die Kurve kriegen\", \"sich von etwas erholen\" (Krankheit, Schreck, etc.), [[sich derrappeln]]"}]'::jsonb, 'Noch da Kraunkheid hoda si nii wiida so richtig dafaungan!'),
  ('noch-da-kraunkheid-hoda-si-nii-wiida-so-richtig-dafaungan', 'Noch da Kraunkheid hoda si nii wiida so richtig dafaungan!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Nach der Krankheit hat er sich nie wieder so richtig erfangen!', '[{"kategorie": "wörtlich", "text": "\"Nach der Krankheit ist er nie wieder so richtig genesen!\"  2. Nach dieser Krankheit ist er nie wieder so richtig auf die Beine gekommen!  3. Nach dieser Krankheit hat er sich nie wieder so richtig [[derrappelt]]!"}]'::jsonb, 'si dafaungan'),
  ('dea-easchdn-zwanzg-minuutn-woans-sauschwoch-owa-daunn-haum-sa-si-dafaungan-und-no-drei-tialn-gschossn', 'Dea easchdn zwanzg Minuutn woans sauschwoch, owa daunn haum sa si dafaungan und no drei Tialn gschossn!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Die ersten zwanzig Minuten waren sie sauschwach, aber dann haben sie sich erfangen und noch drei Tore geschossen!', '[{"kategorie": "wörtlich", "text": "\"Sie starteten sauschwach, doch dann konnten sie sich stabilisieren und das Spiel mit drei Treffern noch drehen!\"  2. Nach einem miserablen Start fanden sie zu alter Stärke zurück und drehten die Partie mit drei Toren noch zu ihren Gunsten!  3. Nach schwachen ersten Minuten stabilisierten sie die Abwehrarbeit, gewannen die Spielkontrolle zurück und erzielten noch drei entscheidende Tore zum Sieg!"}]'::jsonb, ''),
  ('loss-de-eadaepfaen-ned-so-laung-in-da-lood-sunst-dafaeuns-da', 'Loss de Eadäpfän ned so laung in da Lood - sunst dafäuns da!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Lass die Erdäpfeln nicht so lang in der Lade – sonst derfäulen''s dir!', '[{"kategorie": "wörtlich", "text": "\"Lass die Kartoffeln nicht so lang in der Lade – sonst verfaulen sie dir!\"  2. Lager die Kartoffeln nicht zu lange, sonst setzen sie Fäulnis an!  3. Kartoffeln dürfen nicht zu lange liegen, sonst beginnen sie zu verrotten!"}]'::jsonb, ''),
  ('wea-hod-da-den-schaas-dazoeoed', 'Wea hod da den Schaas dazööd?', '', '', '', 'Wiener Sprüche, die sitzen!', 'Wer hat dir diesen Schas erzählt?', '[{"kategorie": "wörtlich", "text": "\"Wer hat dir denn diesen Unsinn erzählt?\"  2. Wer hat dir so einen Mist ins Ohr gesetzt?  3. Wer hat dir denn diesen Stuss serviert?"}]'::jsonb, ''),
  ('wem-host-de-marii-geebm-und-wem-juckd-des-jetzt-iwahaupt-noo', 'Wem host de Marii geebm - und wem juckd des jetzt iwahaupt noo?', '', '', '', 'Wiener Gaunersprache', 'Wem hast du die Marie gegeben - und wen juckt das jetzt überhaupt noch?', '[{"kategorie": "wörtlich", "text": "\"Wem hast du die Kohle gegeben - und wen juckt das jetzt überhaupt noch?\"  2.Wem hast du das Geld gegeben – und wen interessiert das jetzt überhaupt noch?  3. Wem hast du die Kohle in die Hand gedrückt – und wer schert sich da jetzt noch drum?  4. Wem hast du den Zaster zukommen lassen - und wen kratzt das jetzt überhaupt noch?"}]'::jsonb, ''),
  ('waunn-di-wea-froogd-obsd-wem-von-deena-kennsd-schittlsd-in-kopf-und-soogsd-laut-na', 'Waunn di wea froogd, obsd wem von deena kennsd, schittlsd in Kopf und soogsd laut ''Na''!', '', '', '', 'Wiener Gaunersprache', 'Wenn dich wer fragt, ob du wen von denen kennst, schüttelst du den Kopf und sagst ''Nein''!', '[{"kategorie": "wörtlich", "text": "\"Wenn dich jemand fragt, ob du irgendjemanden von denen kennst, schüttelst du den Kopf und sagst laut ''Nein''!\"  2. \"Wenn wer fragt, ob du da wen kennst – Kopf schütteln und laut ‚Nein‘ sagen!\"  3. \"Kommt wer mit Fragen, ob du da jemanden kennst – Verneinen. Deutlich. Kein Blick zur Seite, kein Zucken. Nur: ‚Nein‘!\""}]'::jsonb, ''),
  ('oida-i-bin-sowos-von-dafruan-i-brauch-easchd-amoi-an-taeae', 'Oida, I bin sowos von dafruan - I brauch easchd amoi an Tää!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Alter, ich bin sowas von derfroren - ich brauch erst einmal ''nen Tee!', '[{"kategorie": "wörtlich", "text": "\"Mann, Ich bin total durchgefroren – jetzt brauche ich erst mal einen heißen Tee!\"  2. Alter, ich bin halb erfroren - gib mir ''nen heißen Tee, ich muss mich erst mal aufwärmen!  3. Ich bin bis auf die Knochen durchgefroren – mach mir ''nen Tee, ich brauch dringend was Warmes!"}]'::jsonb, ''),
  ('wueuesd-dass-ma-dafrian-oda-draasd-jetzt-endlich-de-haazung-auf', 'Wüüsd, dass ma dafrian - oda draasd jetzt endlich de Haazung auf?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Willst du, dass wir erfrieren - oder drehst du jetzt endlich die Heizung auf?', '[{"kategorie": "wörtlich", "text": "\"Sollen wir uns hier weiter den Hintern abfrieren – oder schaltest du endlich die Heizung ein?\"  2. Sollen wir hier verrecken vor Kälte – oder kommt da noch was von der Heizung?  3. Willst du, dass wir hier alle zu Eiszapfen erstarren, oder heizt du die Bude endlich auf?"}]'::jsonb, ''),
  ('si-dagee', 'si dagee', '', '', '', 'Grundwortschatz Wienerisch', 'sich dergehen', '[{"kategorie": "wörtlich", "text": "\"sich dergehen\" (aus dem intensivierenden Präfix [[der-]]=\"er-\" und \"gehen\"=\"langen\")"}, {"kategorie": "allg.", "text": "\"sich ausgehen\", \"gerade so reichen\", \"noch machbar sein\""}]'::jsonb, 'Des dageed si grod noo so!'),
  ('des-dageed-si-grod-noo-so', 'Des dageed si grod noo so!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das dergeht sich grad noch so!', '[{"kategorie": "wörtlich", "text": "\"Das geht sich grad noch so aus!\"  2. Das lässt sich gerade noch einrichten!  3. Das wird knapp, aber es ist noch machbar!"}]'::jsonb, 'si dagee'),
  ('dea-glengd-ned-auffe', 'Dea glengd ned auffe!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Der g''lengt nicht rauf', '[{"kategorie": "wörtlich", "text": "\"Er kommt mit der Hand oben nicht ran!\"  2. Er kann mit der Hand nicht bis ganz nach oben greifen!  3. Er reicht nicht bis ganz nach oben hin!  3. Seine Reichweite ist zu kurz - er ist zu klein, um da hinaufzufassen!"}]'::jsonb, ''),
  ('si-glengd-ned-ume', 'Si glengd ned ume!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Sie g''lengt nicht rüber!', '[{"kategorie": "wörtlich", "text": "\"Sie langt mit der Hand nicht bis rüber!\"  2. \"Sie ist zu klein, um mit der Hand rüberzufassen!  3. Ihre Reichweite ist zu kurz - sie langt nicht ganz rüber!"}]'::jsonb, ''),
  ('des-trum-aufn-kastl-dagleeng-i-ned', 'Des Trum aufn Kastl dagleeng I ned!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das Trumm auf dem Kasten derglenge ich nicht!', '[{"kategorie": "wörtlich", "text": "\"An das Ding auf dem Kasten komme ich mit der Hand nicht dran!\"  2. Ich kann das Teil da oben auf dem Schrank mit der Hand nicht erreichen!  3. Das Riesending da oben auf dem Kasten ist außer Reichweite für mich!"}]'::jsonb, ''),
  ('den-hods-dagleengd', 'Den hods dagleengd!', '', '', '', 'Tod und Sterben auf Wienerisch', 'Den hat es derglengt!', '[{"kategorie": "wörtlich", "text": "\"Den hat es erwischt!\"  2. \"Den hat das Unglück ereilt!\"  3. \"Den hat sich der Tod gegriffen!\"  4. \"Den hat der Tod zu sich geholt!\""}]'::jsonb, ''),
  ('si-dangleengds-ned', 'Si dangleengds ned!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Sie derglengt es nicht', '[{"kategorie": "wörtlich", "text": "\"Sie langt nicht bis ganz nach oben!\"  2.  \"Sie kommt mit der Hand nicht bis ganz nach oben dran!\"  3. \"Sie kann mit der Hand nicht bis ganz nach oben fassen!\"  4. \"Ihre Reichweite ist zu kurz, um bis ganz nach oben zu greifen!\""}]'::jsonb, ''),
  ('gleng-ma-in-haumma-ume', 'Gleng ma in Haumma ume!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'G''leng mir den Hammer rüber!', '[{"kategorie": "wörtlich", "text": "\"Lang mir den Hammer rüber!\"  2. Reich mir den Hammer herüber!  3. Schieb mir den Hammer rüber!  4. Drück mir den Hammer in die Hand!"}]'::jsonb, ''),
  ('des-goeoed-hod-ned-glaungt', 'Des Gööd hod ned glaungt!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das Geld hat nicht gelangt!', '[{"kategorie": "wörtlich", "text": "\"Das Geld hat nicht gereicht!\"  2. Finanziell ist es sich nicht ausgegangen!  3. Das Budget hat nicht ausgereicht!  4. Die Mittel waren zu knapp bemessen!"}]'::jsonb, ''),
  ('gimma-in-fliangpracka-damit-i-de-deppade-goeoesn-endlich-daklaesch', 'Gimma in Fliangpracka, damit I de deppade Göösn endlich dakläsch!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Gib mir den Fliegenpracker, damit ich die depperte Gelse endlich derklesch!', '[{"kategorie": "wörtlich", "text": "\"Gib mir díe Fliegenklatsche, damit ich die blöde Gelse endlich erschlage!\"  2. Her mit der Fliegenklatsche, damit ich die Stechmücke endlich plattmache!  3. Bitte hol mir die Fliegenklatsche – ich erledige diesen Blutsauger jetzt endgültig!"}]'::jsonb, ''),
  ('den-hods-auf-da-autobaun-daklaeschd', 'Den hods auf da Autobaun dakläschd!', '', '', '', 'Wiener Mechaniker-Slang', 'Den hat es auf der Autobahn derklescht!', '[{"kategorie": "wörtlich", "text": "\"Den hat es auf der Autobahn zerlegt!\"  2. Der ist auf der Autobahn verunglückt!  3. Den hat es auf der Autobahn böse erwischt!"}]'::jsonb, ''),
  ('waunnsd-de-goeoesn-ned-boid-dagidschd-gee-i-ins-woonzimma-schloofn', 'Waunnsd de Göösn ned boid dagidschd, gee I ins Woonzimma schloofn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wenn du die Gelse nicht bald dergitscht, gehe ich ins Wohnzimmer schlafen!', '[{"kategorie": "wörtlich", "text": "\"Wenn du die Gelse nicht bald plattmachst, gehe ich ins Wohnzimmer schlafen!\"  2. Wenn du den Blutsauger nicht bald erwischt, schlafe ich draußen auf der Couch!  3. Wenn du das Viech nicht bald erledigst, zieh ich um ins Gästebett!"}]'::jsonb, ''),
  ('den-hod-de-leiplaunkn-dagidschd', 'Den hod de Leiplaunkn dagidschd!', '', '', '', 'Wiener Mechaniker-Slang', 'Den hat die Leitplanke dergitscht!', '[{"kategorie": "wörtlich", "text": "\"Den hat die Leitplanke zerdrückt!\"  2. Den hat’s voll aufgestellt – direkt in die Leitplanke!  3. Der ist volle Lotte gegen die Leitplanke gecrasht!  4. Der hat die Leitplanke erwischt und ist daran zerschellt!"}]'::jsonb, ''),
  ('daklotsch-de-goeoesn-min-schlapfn-oda-soi-i-da-in-fliangpracka-hoin', 'Daklotsch de Göösn min Schlapfn - oda soi I da in Fliangpracka hoin?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Derklatsch'' die Gelse mit dem Schlapfen - oder soll ich dir den Fliegenpracker holen?', '[{"kategorie": "wörtlich", "text": "\"Erschlag die Gelse mit dem Schlappen - oder soll ich dir die Fliegenklatsche holen?\"  2. Zerklatsch das Mistvieh mit dem Schlappen – oder brauchst du den Fliegenpracker?  3. Mach den Blutsauger mit dem Pantoffel platt - oder soll ich dir die Fliegenklatsche bringen?"}]'::jsonb, ''),
  ('den-hod-de-haeae-daklotschd', 'Den hod de Hää daklotschd!', '', '', '', 'Wiener Gaunersprache', 'Den hat die Höh derklatscht!', '[{"kategorie": "wörtlich", "text": "\"Den hat die Polizei zur Strecke gebracht!\"  2. Den hat die Polizei dingfest gemacht!  3. Der wurde von den Bullen aus dem Verkehr gezogen!  4. Den haben die Bullen unschädlich gemacht!"}]'::jsonb, ''),
  ('si-dakreizign', 'si dakreizign', '', '', '', 'Echte Wiener Schmähperlen', 'sich derkreuzigen', '[{"kategorie": "wörtlich", "text": "\"sich derkreuzigen\" (aus dem intensivierenden Präfix [[der-]]=\"zer-\" und [[kreuzigen]]=\"meucheln\")"}, {"kategorie": "allg.", "text": "\"sich aufopfern\" (eigtl. \"sich selbst ans Kreuz nageln\"), sich aufreiben, sich abplacken, [[sich]] zersprageln, [[sich]] zerfransen"}]'::jsonb, 'I dakreizig mi do fia eich - und ees riads ned amoi in klaan Finga fia mi!'),
  ('i-dakreizig-mi-do-fia-eich-und-ees-riads-ned-amoi-in-klaan-finga-fia-mi', 'I dakreizig mi do fia eich - und ees riads ned amoi in klaan Finga fia mi!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich derkreuzig'' mich da für euch - und ihr rührt nicht einmal den kleinen Finger für mich!', '[{"kategorie": "wörtlich", "text": "\"Ich opfere mich da für euch auf - und ihr rührt nicht einmal den kleinen Finger für mich!\"  2. Ich reiße mir da alle Beine für euch aus - und euch juckt das nicht mal im kleinen Zeh!  3. Ich zerfranse mich da für euch - und ihr lasst mich verrecken!"}]'::jsonb, ''),
  ('wauma-des-ois-heit-noo-damochn-hauma-muang-a-rua', 'Wauma des ois heit noo damochn, hauma muang a Rua!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Wenn wir das alles heut noch dermachen, haben wir morgen eine Ruh!', '[{"kategorie": "wörtlich", "text": "\"Wenn wir das alles heute noch schaffen, haben wir morgen Ruhe!\"  2. \"Wenn wir das alles heute über die Bühne bringen, ist morgen frei!\"  3. \"Wenn wir das heute noch zu Ende bringen, ist morgen Ruhe angesagt!\""}]'::jsonb, ''),
  ('dea-damochts-nimma-laung', 'Dea damochts nimma laung!', '', '', '', 'Tod und Sterben auf Wienerisch', 'Der dermacht es nicht mehr lange!', '[{"kategorie": "wörtlich", "text": "\"Der wird nicht mehr lange durchhalten!\"  2. \"Der scheint bald am Ende zu sein!\"  3. Es sieht nicht so aus, als würde er es noch lange schaffen!  4. Der steht schon mit einem Fuß im Grab!"}]'::jsonb, ''),
  ('deamoin-ois-schdudent-in-wean-hob-i-mea-im-beisl-gleand-ois-in-da-uni', 'Deamoin ois Schdudent in Wean hob I mea im Beisl gleand ois in da Uni!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Dermalig als Student in Wien, hab ich im Beisl mehr gelernt als in der Uni!', '[{"kategorie": "wörtlich", "text": "\"Damals als Student in Wien, hab ich im Beisl mehr gelernt als in der Uni!\"  2. Seinerzeit als Student in Wien hab ich im Wirtshaus mehr über das Leben gelernt als in jedem Hörsaal!  3. Zu jener Zeit, als ich noch als Student in Wien war, hab ich meine eigentliche Bildung nicht an der Uni, sondern am Stammtisch gemacht!"}]'::jsonb, ''),
  ('i-gib-aeae-imma-nooch-owa-deamoin-ned', 'I gib ää imma nooch - owa deamoin ned!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Ich gebe eh immer nach - aber dermalig nicht!', '[{"kategorie": "wörtlich", "text": "\"Ich gebe eh immer nach - aber dieses Mal nicht!\"  2. Ich lasse sonst eh immer mit mir reden – aber diesmal nicht!  3. Normalerweise lenke ich ein – aber jetzt nicht!"}]'::jsonb, ''),
  ('si-dameakn', 'si dameakn', '', '', '', 'Grundwortschatz Wienerisch', 'sich dermerken', '[{"kategorie": "wörtlich", "text": "\"sich dermerken\" (aus dem intensivierenden Präfix [[der-]]=\"er-\" und [[merken]]=\"fassen\")"}, {"kategorie": "allg.", "text": "sich etwas merken, sich etwas einprägen, sich etwas verinnerlichen, im Gedächtnis behalten"}]'::jsonb, 'Des dameak I ma nii!'),
  ('des-dameak-i-ma-nii', 'Des dameak I ma nii!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das dermerke ich mir nie!', '[{"kategorie": "wörtlich", "text": "\"Das werde ich mir nie merken können!\"  2. Das geht einfach nicht in meinen Kopf!  3. Das bleibt bei mir einfach nicht hängen!  4. Keine Chance, dass ich mir das merke!"}]'::jsonb, 'si dameakn'),
  ('dameaksd-da-du-denn-goa-nix', 'Dameaksd da du denn goa nix?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Dermerkst du dir denn gar nichts?', '[{"kategorie": "wörtlich", "text": "\"Kannst du dir denn gar nichts merken?\"  2. \"Behältst du denn überhaupt irgendwas?\"  3. Bei dir bleibt überhaupt nichts hängen, gelt?"}]'::jsonb, ''),
  ('des-dapock-i-mit-links', 'Des dapock I mit links!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das derpack ich mit links!', '[{"kategorie": "wörtlich", "text": "\"Das schaffe ich mit links!\"  2. Das schaffe ich ganz locker!  3. Das meistere ich problemlos!"}]'::jsonb, ''),
  ('i-dapock-des-ollas-nimma-vueue-zvueue-stress', 'I dapock des ollas nimma - vüü zvüü Stress!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich derpack das alles nimmer - viel zu viel Stress!', '[{"kategorie": "wörtlich", "text": "\"Ich stehe das alles nicht mehr durch - viel zu viel Stress!\"  2. Ich verkrafte das alles nicht mehr – dieser Stress bringt mich um!  3. Ich schaffe das nicht mehr - mir wächst alles über den Kopf!"}]'::jsonb, ''),
  ('du-hostas-daroodn', 'Du hostas daroodn!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Du hast es derraten!', '[{"kategorie": "wörtlich", "text": "\"Du hast den Nagel auf den Kopf getroffen!\"; \"Dein Tipp war goldrichtig - stimmt genau!\"; \"Du hast genau ins Schwarze getroffen! Bingo!\""}, {"kategorie": "fig.", "text": "\"Du kommst wie gerufen!\"; \"Dein Timing ist perfekt!\"; \"Du kommst genau zur rechten Zeit!\""}]'::jsonb, 'Du hostas genau daroodn - I ziags Braadl grod ausn Roa!'),
  ('du-hostas-daroodn-nua-bares-is-waares', 'Du hostas daroodn - nua Bares is Waares!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Du hast es erraten - nur Bares ist Wahres!', '[{"kategorie": "wörtlich", "text": "\"Du hast den Nagel auf den Kopf getroffen - nur Bares ist Wahres!\"  2. Dein Tipp ist goldrichtig - hier zahlt man Cash!  3. Bingo, Volltreffer - Geld bar auf die Hand, sonst nix!"}]'::jsonb, 'Du hostas daroodn!'),
  ('du-hostas-genau-daroodn-i-ziags-braadl-grod-ausn-roa', 'Du hostas genau daroodn - I ziags Braadl grod ausn Roa!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Du hast es genau erraten - ich ziehe das Bratl gerade aus dem Rohr!', '[{"kategorie": "wörtlich", "text": "\"Du kommst genau zur rechten Zeit - ich hol den Braten gerade aus dem Ofen!\"  2. Du kommst wirklich im allerbesten Moment – der Braten ist gerade fertig!  3. Na, wenn das kein Timing ist – ich wollt grad auftischen!"}]'::jsonb, 'Du hostas daroodn!'),
  ('des-is-ned-zum-dareidn', 'Des is ned zum Dareidn!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das ist nicht zum Derreiten!', '[{"kategorie": "wörtlich", "text": "\"Das ist nicht zu schaffen!\"  2. Das ist nicht hinzukriegen!  3. Das lässt sich nicht bewältigen!"}]'::jsonb, ''),
  ('de-suusl-des-wueuede-luada-hod-no-kaana-dariidn', 'De Suusl, des wüüde Luada, hod no kaana dariidn!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Die Susl, dieses wilde Luder, hat noch keiner derritten!', '[{"kategorie": "wörtlich", "text": "\"Die Susi, dieses wilde Luder, hat noch keiner in den Griff bekommen!\"  2. Die Susi ist ein wildes Pferd, das keiner satteln kann!  3. Die Susi, dieses wilde Weibsbild, lässt sich von niemandem zureiten!"}]'::jsonb, ''),
  ('i-sogs-da-ealich-de-oide-dapuuda-i-ned', 'I sogs da ealich - de Oide dapuuda I ned!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Ich sag''s dir ehrlich - die Alte derpuder'' ich nicht!', '[{"kategorie": "wörtlich", "text": "\"Ich sag''s dir ehrlich - die Alte krieg ich nicht gevögelt!\"  2. Ich geb''s zu - der Alten bin ich sexuell nicht gewachsen!\"  3. Ich gestehe - die Frau ist eine Nummer zu groß für mich, die krieg ich nicht gebacken!"}]'::jsonb, ''),
  ('oone-mi-bist-daschossn', 'Oone mi bist daschossn!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Ohne mich bist du derschossen!', '[{"kategorie": "wörtlich", "text": "\"Ohne mich bist du erledigt!\"  2. Ohne mich bist du geliefert!  3. Ohne mich bist du dem Untergang geweiht!  4. Ohne mich kannst du dir die Kugel geben!"}]'::jsonb, ''),
  ('si-daschiassn', 'si daschiassn', '', '', '', 'Grundwortschatz Wienerisch', 'sich derschießen', '[{"kategorie": "wörtlich", "text": "\"sich derschießen\" (aus dem intensivierenden Präfix [[der-]]=\"er-\" und \"schießen\"=\"ballern\")"}, {"kategorie": "allg.", "text": "\"sich erschießen\", \"sich die Kugel geben\", \"Selbstmord begehen\", [[si zwaa Määta tiafa bringan]]"}]'::jsonb, 'Waunn des so weidageed, kaunn I mi daschiassn!'),
  ('waunn-des-so-weidageed-kaunn-i-mi-daschiassn', 'Waunn des so weidageed, kaunn I mi daschiassn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wenn das so weitergeht, kann ich mich derschießen!', '[{"kategorie": "wörtlich", "text": "\"Wenn das so weitergeht, kann ich mich erschießen!\"  2. \"Wenn sich nicht bald was ändert, kann ich mir die Kugel geben!\"  3. \"Wenn das noch lange so weiterläuft, kann ich mich in die Luft jagen!\""}]'::jsonb, 'si daschiassn'),
  ('si-dahaengan', 'si dahängan', '', '', '', 'Grundwortschatz Wienerisch', 'sich derhängen', '[{"kategorie": "wörtlich", "text": "\"sich derhängen\" (aus dem intensivierenden Präfix [[der-]]=\"er-\" und \"hängen\"=\"henken\")"}, {"kategorie": "allg.", "text": "\"sich erhängen\", \"sich aufhängen\", \"sich durch Erhängen töten\", \"den Strick wählen\", [[si ins Pendl haun]], [[si ins Hangal schmeissn]]"}]'::jsonb, 'si ins Pendl haun'),
  ('dahaengan-daschiassn-oda-dawiang-suachs-da-aus', 'Dahängan, daschiassn oda dawiang? Suachs da aus!', '', '', '', 'Wiener Gaunersprache', 'Erhängen, erschießen oder erwürgen? Such''s dir aus!', '[{"kategorie": "wörtlich", "text": "\"Erhängen, erschießen oder erwürgen? Du hast die Wahl!\"  2. \"Kugel oder Strick? Ich lass dir die Wahl!\"  3. Erhängen, erschießen oder erwürgen? Dein Wunsch geschehe!\""}]'::jsonb, 'si dahängan'),
  ('eam-hods-dabaatzd-da-laastla-is-direkt-iwa-eam-driiwagfoan', 'Eam hods dabaatzd - da Laastla is direkt iwa eam driiwagfoan!', '', '', '', 'Tod und Sterben auf Wienerisch', 'Ihn hat es derbaatzt - der Lastler ist direkt über ihn drübergefahren!', '[{"kategorie": "wörtlich", "text": "\"Er wurde zerquetscht - der Lastwagen ist direkt über ihn drübergefahren!\"  2. Der LKW walzte ihn nieder – er wurde regelrecht zermalmt!  3. Der LKW hat ihn einfach über den Haufen gefahren - er wurde genadenlos niedergewalzt!"}]'::jsonb, ''),
  ('um-a-hoa-war-i-in-mein-oeoe-aa-noo-darsoffn-owa-ned-im-wei-sondan-in-da-eiganan-boodwaunn', 'Um a Hoa war I in mein Öö aa noo darsoffn - owa ned im Wei, sondan in da eiganan Boodwaunn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Um ein Haar wäre ich in meinem Öl auch noch darsoffen - aber nicht im Wein, sondern in der eigenen Badewanne!', '[{"kategorie": "wörtlich", "text": "\"In meinem Vollrausch wäre ich um ein Haar auch noch ersoffen - aber nicht im Wein, sondern in der eigenen Badewanne!\"  2. Im Vollsuff hätt ich mich beinah selber ersäuft – nicht im Wein, sondern in der eigenen Badewanne!  3. In meiner [[Fett]]''n hätt ich mich fast selbst versenkt – nicht im Wein, sondern in der eigenen Wanne!"}]'::jsonb, ''),
  ('des-darsauf-i-ned-allaanich', 'Des darsauf I ned allaanich!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Das darsauf'' ich nicht alleine!', '[{"kategorie": "wörtlich", "text": "\"Das krieg ich allein nicht weggetrunken!\"  2. \"Das kann ich nicht alles alleine austrinken!\"  3. Allein sauf ich das nicht runter - da müsst ich ja drei Tage dran trinken!"}]'::jsonb, ''),
  ('um-a-hoa-war-i-in-mein-oeoe-aa-noo-dasoffn-owa-ned-im-wei-sondan-in-da-eiganan-boodwaunn', 'Um a Hoa war I in mein Öö aa noo dasoffn - owa ned im Wei, sondan in da eiganan Boodwaunn!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Um ein Haar wäre ich in meinem Öl auch noch dersoffen - aber nicht im Wein, sondern in der eigenen Badewanne!', '[{"kategorie": "wörtlich", "text": "\"In meinem Vollrausch wäre ich um ein Haar auch noch ersoffen - aber nicht im Wein, sondern in der eigenen Badewanne!\"  2. Im Vollsuff hätt ich mich beinah selber ersäuft – nicht im Wein, sondern in der eigenen Badewanne!  3. In meiner [[Fett]]''n hätt ich mich fast selbst versenkt – nicht im Wein, sondern in der eigenen Wanne!"}]'::jsonb, ''),
  ('des-dasauf-i-ned-allaanich', 'Des dasauf I ned allaanich!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Das dersauf'' ich nicht alleine!', '[{"kategorie": "wörtlich", "text": "\"Das krieg ich allein nicht weggetrunken!\"  2. \"Das kann ich nicht alles alleine austrinken!\"  3. Allein sauf ich das nicht runter - da müsst ich ja drei Tage dran trinken!"}]'::jsonb, ''),
  ('des-dabloos-i-nimma', 'Des dabloos I nimma!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das derblase ich nimmer!', '[{"kategorie": "wörtlich", "text": "\"Dafür reicht meine Puste nicht mehr!\"  2. Das schaffe ich nicht mehr!  3. Dafür hab ich keinen Dampf mehr!  4. Da steige ich aus!"}]'::jsonb, ''),
  ('des-g3-in-da-drittn-oktaav-hoda-daunn-nimma-dabloosn', 'Des g3 in da drittn Oktaav hoda daunn nimma dabloosn!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Das g3 in der dritten Oktave hat er dann nicht mehr derblasen!', '[{"kategorie": "wörtlich", "text": "\"Beim g3 war für ihn Schluss – da hat die Luft nicht mehr gereicht!\"  2. Der hohe Ton war einfach zu viel – g3 hat er nicht mehr geschafft!  3. Beim g3 musste er absetzen - da war''s dann zu Ende mit der Puste!"}]'::jsonb, ''),
  ('si-schaud-heit-a-wengl-dadruckd-aus', 'Si schaud heit a wengl dadruckd aus!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Sie schaut heute ein wenig zerdrückt aus!', '[{"kategorie": "wörtlich", "text": "\"Sie wirkt heute ein wenig angeschlagen!\"  2. Sie sieht heute ziemlich zerknautscht aus!   3. Sie wirkt heute nicht ganz frisch!"}]'::jsonb, ''),
  ('de-aantn-schaut-oag-dadruckd-aus', 'De Aantn schaut oag dadruckd aus!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die Ente schaut arg derdrückt aus!', '[{"kategorie": "wörtlich", "text": "\"Die Ente schaut arg zerdrückt aus!\"  2. Die Ente wirkt ziemlich lädiert!  3. Die Ente schaut ziemlich zerknautscht drein!"}]'::jsonb, ''),
  ('heit-kaunnsd-da-an-uni-obschluss-fost-schoo-daguugln', 'Heit kaunnsd da an Uni-Obschluss fost schoo daguugln!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Heute kannst du dir einen Uni-Abschluss fast schon dergoogeln!', '[{"kategorie": "wörtlich", "text": "\"Heute lässt sich ein Uni-Abschluss fast schon ergoogeln!\"  2. Wozu studieren, wenn man sich sein Wissen auch ergoogeln kann?  3. Heute brauchst du für einen Uni-Abschluss nur noch WLAN - dann kannst du dir deinen Uni-Abschluss im Internet ergoogeln!"}]'::jsonb, ''),
  ('draa-di-sunst-kaunnst-wos-daleebm', 'Draa di, sunst kaunnst wos daleebm!', '', '', '', 'Wiener Gaunersprache', 'Dreh'' dich, sonst kannst du was derleben!', '[{"kategorie": "wörtlich", "text": "\"Zieh Leine, sonst kannst du was erleben!\"  2. Verzieh dich, sonst geht''s dir an den Kragen!  3. Mach [[Meter]], sonst kracht''s!"}]'::jsonb, ''),
  ('bitte-schleich-di-ned-so-au-du-daschrecksd-mi-a-jeeds-moi', 'Bitte schleich di ned so au - du daschrecksd mi a jeeds Moi!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Bitte schleich dich nicht so an – du erschreckst mich ein jedes Mal!', '[{"kategorie": "wörtlich", "text": "\"Schleich dich bitte nicht so an – du jagst mir jedes Mal einen Schreck ein!\"  2. Bitte komm nicht so lautlos – du erschreckst mich jedes Mal zu Tode!  3. Du musst dich nicht anschleichen wie ein Ninja – oder willst du mir jedes Mal aufs Neue einen Schrecken einjagen?"}]'::jsonb, ''),
  ('waunnsd-blauliachd-siichsd-deafsd-ned-daschreckn', 'Waunnsd Blauliachd siichsd, deafsd ned daschreckn!', '', '', '', 'Wiener Gaunersprache', 'Wennst Blaulicht siehst, darfst nicht erschrecken!', '[{"kategorie": "wörtlich, Gaunerjargon", "text": "\"Wenn''s blau blitzt vor der Tür, nur nicht zusammenzucken!\"  2. Wenn die Bullen anrollen, keine Panik – bleibst schön locker!  3. Wenn die Kieberer aufkreuzen, nur nicht in die Hose machen!"}]'::jsonb, ''),
  ('daschreck-di-ned-waunnsd-mei-oide-mit-iara-neichn-frisua-siichsd', 'Daschreck di ned, waunnsd mei Oide mit iara neichn Frisua siichsd!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Derschreck dich nicht, wenn du meine Alte mit ihrer neuen Frisur siehst!', '[{"kategorie": "wörtlich", "text": "\"Erschreck dich bitte nicht zu Tode, wenn du meine Alte mit ihrer neuen Frisur siehst!\"  2. Mach dir nur nicht ins Hemd, solltest du meine Alte mit ihrer neuen Frisur erspähen!  3. Halt dich fest und scheiß nicht in die Hose, wenn du meine Alte mit ihrer neuen Mähne siehst!"}]'::jsonb, ''),
  ('da-ochs-hod-eam-daschdessn', 'Da Ochs hod eam daschdessn!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Der Ochs hat ihn derstoßen!', '[{"kategorie": "wörtlich", "text": "\"Der Ochse hat ihn zu Tode gestoßen!\"  2. Der Ochse hat ihn mit einem Stoß tödlich verletzt!  3. Er wurde von einem Ochsen zu Boden gestoßen und tödlich verletzt!"}]'::jsonb, ''),
  ('si-daschdessn', 'si daschdessn', '', '', '', 'Grundwortschatz Wienerisch', 'sich derstessen', '[{"kategorie": "wörtlich", "text": "\"sich derstössen\" (aus dem intensivierenden Präfix [[der-]]=\"er-\" und [[stössen]]=\"stoßen\")"}, {"kategorie": "eigtl.", "text": "\"sich erstoßen\" (so fest gegen etwas stoßen, dass man zu Tode kommt oder schwer verletzt wird), \"sich zu Tode stoßen\", \"verunglücken\", \"sich tödlich oder schwer verletzen\", \"zu Tode kommen\""}, {"kategorie": "scherzhaft für", "text": "\"sich zu Tode schuften\", \"sich tothackeln\", \"sich kaputtarbeiten\", \"sich zu Tode verausgaben\", (Deutschland): \"sich zu Tode malochen\""}]'::jsonb, 'Da Schuali hod se heit mit sein Eisn daschdessn!'),
  ('da-schuali-hod-se-heit-mit-sein-eisn-daschdessn', 'Da Schuali hod se heit mit sein Eisn daschdessn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der Schurli hat sich heute mit seinem Eisen derstoßen!', '[{"kategorie": "wörtlich", "text": "\"Der Georg ist heute mit seinem Motorrad tödlich verunglückt!\"  2. Ein Sturz mit dem Motorrad wurde Georg heute zum Verhängnis!  3. Der Schurli ist heut mit seinem Eisen so blöd gefallen, dass er gestorben ist!"}]'::jsonb, 'si daschdessn'),
  ('hackl-ned-wiara-wueueda-do-kunnt-ma-si-daschdessn', 'Hackl ned wiara Wüüda - do kunnt ma si daschdessn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Hackel nicht wie ein Wilder - davon könnte man sich den Tod holen!', '[{"kategorie": "wörtlich", "text": "\"Schufte nicht wie ein Verrückter – davon geht man am Ende noch drauf!\"  2. Arbeite nicht wie ein Wahnsinniger – sonst könntest du dich am Ende noch tothackeln!  3. Maloche nicht wie ein Irrer - daran sind einige schon gestorben!"}]'::jsonb, 'si daschdessn'),
  ('waunnsd-in-baam-ned-giassd-dadiiad-a-da', 'Waunnsd in Baam ned giassd, dadiiad a da!', '', '', '', 'Echte Wiener Schmähperlen', 'Wenn du den Baum nicht gießt, derdürrt er dir!', '[{"kategorie": "wörtlich", "text": "\"Wenn du den Baum nicht gießt, verdörrt er dir!\"  2. Wenn du dem Baum kein Wasser gibst, wird er dir unter deinen Augen vertrocknen!  3. Wenn du ihn nicht regelmäßig gießt, wird dir der Baum eingehen!"}]'::jsonb, ''),
  ('deraweeng-is-haab-auf-mi-bist-da-sicha', 'Deraweeng is haab auf mi? - Bist da sicha?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Deretwegen ist sie harb auf mich ? - Bist du sicher?', '[{"kategorie": "wörtlich", "text": "\"Deswegen ist sie böse auf mich? – Bist du sicher?\"  2. \"Wegen dem ist sie verärgert über mich? – Wirklich?\"  3. Meinst du wirklich, das ist der Grund, warum sie auf mich sauer ist?  4. Deswegen ist sie angepisst? – Ernsthaft?"}]'::jsonb, ''),
  ('i-kenn-des-puppal-ned-deraweeng-a-sei-oide-schdeelossn-hod', 'I kenn des Puppal ned, deraweeng a sei Oide schdeelossn hod!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Ich kenne das Pupperl nicht, deretwegen er seine Alte hat stehenlassen!', '[{"kategorie": "wörtlich", "text": "\"Ich kenne das Mädel nicht, deretwegen er seine Frau verlassen hat!\"  2. Ich weiß nicht, wer die Frau ist, wegen der er seine Alte hat sitzenlassen!  3. Keine Ahnung, wer die Tussi ist, für die er sich von seiner Alten getrennt hat!"}]'::jsonb, ''),
  ('dessatweeng-is-haab-auf-mi-bist-da-sicha', 'Dessatweeng is haab auf mi? - Bist da sicha?', '', '', '', 'Wiener Sprüche, die sitzen!', 'Dessetwegen ist sie harb auf mich ? - Bist du sicher?', '[{"kategorie": "wörtlich", "text": "\"Deswegen ist sie böse auf mich? – Bist du sicher?\"  2. \"Wegen dem ist sie verärgert über mich? – Wirklich?\"  3. Meinst du wirklich, das ist der Grund, warum sie auf mich sauer ist?  4. Deswegen ist sie angepisst? – Ernsthaft?"}]'::jsonb, ''),
  ('i-wissad-kaan-grund-ned-dessatweengs-eam-ausseschmeissn-kunntn', 'I wissad kaan Grund ned, dessatweengs eam ausseschmeissn kunntn!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Ich wüsste keinen Grund nicht, dessetwegen sie ihn rausschmeißen könnten!', '[{"kategorie": "wörtlich", "text": "\"Mir ist kein Grund bekannt, aus dem sie ihn entlassen könnten!\"  2. \"Mir fällt kein Grund ein, warum sie ihn rauswerfen sollten!\"  3. Ich kenne keinen Grund, weshalb sie ihn rausschmeißen könnten!"}]'::jsonb, ''),
  ('ea-hod-ka-eiloodung-kriagd-deahoibm-isa-ned-kumma', 'Ea hod ka Eiloodung kriagd - deahoibm isa ned kumma!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Er hat keine Einladung gekriegt - derethalben ist er nicht gekommen!', '[{"kategorie": "wörtlich", "text": "\"Er hat keine Einladung erhalten – deshalb ist er nicht gekommen!\"  2. Er hat keine Einladung bekommen – deswegen blieb er fern!  3. Es war ihm keine Einladung zugegangen, derethalben war er nicht anwesend!"}]'::jsonb, ''),
  ('des-dazaa-i-ned-allaanich', 'Des dazaa I ned allaanich!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das derzerre ich nicht alleine!', '[{"kategorie": "wörtlich", "text": "\"Das kann ich alleine nicht ziehen!\""}, {"kategorie": "", "text": "Das kann ich nicht alleine tragen!  3. Das schaffe ich nicht alleine!  4. Das kann ich nicht alleine stemmen!"}]'::jsonb, ''),
  ('ob-ma-des-datuan-is-mea-ois-frooglich', 'Ob ma des datuan, is mea ois frooglich!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ob wir das dertun, ist mehr als fraglich!', '[{"kategorie": "wörtlich", "text": "\"Ob wir das schaffen, ist mehr als fraglich!\"  2. Es steht in den Sternen, ob wir das hinkriegen!  3. Ob sich das für uns ausgeht, wage ich zu bezweifeln!"}]'::jsonb, ''),
  ('des-kaunnst-deina-groossmuada-darzoeoen', 'Des kaunnst deina Groossmuada darzöön!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Das kannst du deiner Großmutter darzählen!', '[{"kategorie": "", "text": "Das kannst du deiner Großmutter erzählen!  2. Das glaubt nur der Kuckuck!  3. [[Des]] kaunnsd deina Uaschdrumpftant darzöön!"}]'::jsonb, ''),
  ('dem-wear-i-wos-darzoeoen', 'Dem wear I wos darzöön!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Dem werd ich was darzählen!', '[{"kategorie": "wörtlich", "text": "\"Dem werd'' ich was erzählen!\"  2. \"Den werde ich mir zur Brust nehmen!\"  3. \"Dem wird'' ich die Leviten lesen!\"  4. \"Dem werd'' ich was erzählen – aber vom Feinsten!\""}]'::jsonb, ''),
  ('de-blaue-bim', 'de blaue Bim', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'die blaue Bim', '[{"kategorie": "wörtlich", "text": "\"die blaubeschilderte Straßenbahn\" (= der letzte Kurs einer Straßenbahnlinie. Seit 1873 zeigte eine blaue Scheibe am Wagenende an, dass es sich um den letzten Zug handelt. Ab den 1980ern verschwand \"die Blaue\" langsam durch neue Anzeigesysteme [Brosebänder, Matrix] und am 4. März 1995 fuhr die letzte offizielle „Blaue“. Intern wird der Begriff bei den [[Wiener]] Linien und von der Wiener Bevölkerung aber heute noch verwendet)"}, {"kategorie": "allg.", "text": "die letzte Straßenbahn (die spätabends/nachts unmittelbar vor Betriebsschluss noch fährt), \"die [[Blaue]]\", \"die blaue [[Tramway]]"}]'::jsonb, ''),
  ('de-blaue', 'de Blaue', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'die Blaue', '[{"kategorie": "wörtlich", "text": "\"die blaubeschilderte Straßenbahn\" (= der letzte Kurs einer Straßenbahnlinie. Seit 1873 zeigte eine blaue Scheibe am Wagenende an, dass es sich um den letzten Zug handelt. Ab den 1980ern verschwand \"die Blaue\" langsam durch neue Anzeigesysteme [Brosebänder, Matrix] und am 4. März 1995 fuhr die letzte offizielle „Blaue“. Intern wird der Begriff bei den [[Wiener]] Linien und von der Wiener Bevölkerung aber heute noch verwendet)"}, {"kategorie": "allg.", "text": "die letzte Straßenbahn (die spätabends/nachts unmittelbar vor Betriebsschluss noch fährt), [[die blaue Bim]], \"die blaue [[Tramway]]"}]'::jsonb, ''),
  ('i-hob-eam-in-gaunzn-toog-ned-dawischd', 'I hob eam in gaunzn Toog ned dawischd!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Ich habe ihn den ganzen Tag nicht derwischt!', '[{"kategorie": "wörtlich", "text": "\"Ich habe ihn den ganzen Tag nicht erreicht!\"  2. Ich hab ihn den ganzen Tag nicht ans Telefon gekriegt!  3. Er war telefonisch den ganzen Tag nicht zu erreichen!"}]'::jsonb, ''),
  ('haed-i-de-blaue-bim-darwischd-warad-i-ned-easchd-uma-fuenfe-haamkumma', 'Häd I de blaue Bim darwischd, warad I ned easchd uma fünfe haamkumma!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Hätte ich die blaue Bim darwischt, wäre ich nicht erst um fünf heimgekommen!', '[{"kategorie": "wörtlich", "text": "\"Hätte ich die letzte Straßenbahn erwischt, wäre ich nicht erst um fünf Uhr früh heimgekommen!\"  2. Hätte ich die letzte Tramway nicht verpasst, wäre ich nicht erst im Morgengrauen heimgekommen!  3. Hätte ich’s bis zur letzten Bim geschafft, wär ich nicht erst zum Frühstrück dagewesen!"}]'::jsonb, ''),
  ('waunns-di-darwischn-geesd-direkt-in-haeaefn-oone-umweg', 'Waunns di darwischn, geesd direkt in Hääfn - oone Umweg!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wenn sie dich darwischen, gehst du direkt in den Häfen - ohne Umweg!', '[{"kategorie": "wörtlich", "text": "\"Wenn sie dich schnappen, wanderst du schnurstracks ins Gefängnis - ohne Umweg!\"  2. Erwischen sie dich, landest du ohne viel Umschweife gleich direkt im [[Bau]]!  3. Wenn sie dich [[haps]] nehmen, geht''s für dich auf direktem Weg in den Knast!"}]'::jsonb, ''),
  ('setzs-eich-zsaumm-und-darschloogdsas', 'Setzs eich zsaumm und darschloogdsas!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Setzt euch zusammen und darschlagt es!', '[{"kategorie": "wörtlich", "text": "\"Setzt euch zusammen und macht diesem Ding ein Ende!\"  2. Sprecht euch ab und schlagt die ganze Sache tot!  3. Geht das gemeinsam an – und sorgt dafür, dass die Sache dann ein für allemal erledigt ist!"}]'::jsonb, ''),
  ('oide-semmaen-lossn-si-wundaboa-darbreesln', 'Oide Semmän lossn si wundaboa darbreesln!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Alte Semmeln lassen sich wunder bar derbröseln!', '[{"kategorie": "wörtlich", "text": "\"Alte Semmeln lassen sich wunderbar zu Bröseln zerreiben!\"  2. Altbackene Semmeln können ganz leicht zu Bröseln zermahlen werden!  3. Wenn die Semmeln trocken sind, kannst du sie problemlos zu Bröseln zerreiben!"}]'::jsonb, ''),
  ('ollas-wosa-si-aufbaud-hod-dabreesld-eam-jetzd-zwischn-de-finga', 'Ollas, wosa si aufbaud hod, dabreesld eam jetzd zwischn de Finga!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Alles, was er sich aufgebaut hat, derbröselt ihm jetzt zwischen den Fingern!', '[{"kategorie": "wörtlich", "text": "\"Alles, was er sich aufgebaut hat, zerrinnt ihm jetzt zwischen den Fingern!\"  2. Alles, was er sich mühsam aufgebaut hat, fällt ihm jetzt wie ein Kartenhaus zusammen!  3. Alles, was er sich geschaffen hat, zerfällt jetzt Stück für Stück!"}]'::jsonb, ''),
  ('ea-hod-imma-mea-investiad-bis-eam-finanzioeoe-dabreesld-hod', 'Ea hod imma mea investiad, bis eam finanziöö dabreesld hod!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Er hat immer mehr investiert, bis es ihn finanziell darbröselt hat!', '[{"kategorie": "wörtlich", "text": "\"Er hat investiert bis zum Umfallen – und am Ende hat’s ihn zerlegt!\"  2. Er hat immer weiter investiert, bis er finanziellen Schiffbruch erlitten hat!  3. Er hat sein ganzes Geld reingehauen, bis es ihn finanziell zerrissen hat!"}]'::jsonb, ''),
  ('den-hods-beim-drittn-tiarl-darbreesld', 'Den hods beim drittn Tiarl darbreesld!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Den hat es beim dritten Türl darbröselt', '[{"kategorie": "wörtlich, Sportlerjargon", "text": "\"Den hat es beim dritten Tor zerlegt!\"  2. Der ist beim dritten Tor schwer zu Sturz gekommen!  3. Den hat es beim dritten Tor der Länge nach hingehauen!"}]'::jsonb, ''),
  ('ollas-wosa-si-aufbaud-hod-darbreesld-eam-jetzd-zwischn-de-finga', 'Ollas, wosa si aufbaud hod, darbreesld eam jetzd zwischn de Finga!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Alles, was er sich aufgebaut hat, darbröselt ihm jetzt zwischen den Fingern!', '[{"kategorie": "wörtlich", "text": "\"Alles, was er sich aufgebaut hat, zerrinnt ihm jetzt zwischen den Fingern!\"  2. Alles, was er sich mühsam aufgebaut hat, fällt ihm jetzt wie ein Kartenhaus zusammen!  3. Alles, was er sich geschaffen hat, zerfällt jetzt Stück für Stück!"}]'::jsonb, ''),
  ('i-hob-sofuat-daschbechtld-wos-freibia-schdeed', 'I hob sofuat daschbechtld, wos Freibia schdeed!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Ich hab sofort derspechtelt, wo das Freibier steht!', '[{"kategorie": "wörtlich", "text": "\"Ich hab sofort erspäht, wo das Freibier steht!\"  2. Ich hab gleich gesehen, wo das Freibier steht – Spürnase eben!  3. Ich hab’s gerochen, bevor ich’s erspäht hab – Freibier-Instinkt halt!"}]'::jsonb, ''),
  ('schmeiss-eam-in-haumma-ume-dawiafsd-des-ee', 'Schmeiss eam in Haumma ume - dawiafsd des ee?', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Schmeiß ihm den Hammer rüber - derwirfst du das eh?', '[{"kategorie": "wörtlich", "text": "\"Wirf ihm den Hammer rüber – schaffst du das eh so weit?\"  2. Schmeiß den Hammer rüber – kannst du eh so weit werfen?  3. Wirf ihm den Hammer rüber – kriegst du die Weite eh hin?"}]'::jsonb, ''),
  ('de-buama-haum-de-kotz-min-schdaa-dawuafn', 'De Buama haum de Kotz min Schdaa dawuafn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die Buben haben die Katze mit ''nem Stein derworfen!', '[{"kategorie": "wörtlich", "text": "\"Die Jungen haben die Katze mit einem Stein totgeworfen!\"  2. \"Die Buben haben die Katze durch einen Steinwurf getötet!\"  3. \"Die Jungen haben die Katze mit einem Stein erschlagen!\""}]'::jsonb, ''),
  ('si-daweafn', 'si daweafn', '', '', '', 'Grundwortschatz Wienerisch', 'sich derwerfen', '[{"kategorie": "wörtlich", "text": "\"sich derwerfen\" (aus dem intensivierenden Präfix [[der-]]=\"er-\" und [[werfen]]=\"schmeißen\")"}, {"kategorie": "allg.", "text": "\"sich erwerfen\", \"sich zu Tode verausgaben\", \"sich zu viel zumuten\", \"sich zu Tode schuften\", \"sich kaputtarbeiten\""}]'::jsonb, 'Ees geeds an zwitschan und I dawiaf mi do!'),
  ('ees-geeds-an-zwitschan-und-i-dawiaf-mi-do', 'Ees geeds an zwitschan und I dawiaf mi do!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Ihr geht einen zwitschern, und ich derwirf mich da!', '[{"kategorie": "wörtlich", "text": "\"Ihr geht einen heben, und ich schufte mich hier zu Tode!\"  2. \"Ihr geht einen trinken, und ich arbeite mich hier kaputt!\"  3. Ihr kippt euch einen hinter die Binde, während ich mich hier zu Tode schufte!"}]'::jsonb, 'si daweafn'),
  ('de-kiiwara-sonng-dass-de-giatlschnoin-dawiagd-wuan-is', 'De Kiiwara sonng, dass de Giatlschnoin dawiagd wuan is!', '', '', '', 'Wiener Gaunersprache', 'Die Kieberer sagen, dass die Gürtelschnalle erwürgt worden ist!', '[{"kategorie": "wörtlich", "text": "\"Die Bullen sagen, dass das Strichmädchen erwürgt worden ist!\"  2. Die Polizei sagt, das Mädchen vom Straßenstrich wurde erwürgt!  3. Die Ermittler gehen davon aus, dass das Opfer erdrosselt wurde!"}]'::jsonb, ''),
  ('si-dawiang', 'si dawiang', '', '', '', 'Grundwortschatz Wienerisch', 'sich derwürgen', '[{"kategorie": "wörtlich", "text": "\"sich derwürgen\" (aus dem intensivierenden Präfix [[der-]]=\"er-\" und [[würgen]]=\"strangulieren\")"}, {"kategorie": "allg.", "text": "\"sich selbst würgen\", \"sich erwürgen\", \"sich zu Tode verausgaben\", \"sich zu viel zumuten\", \"sich zu Tode schuften\", \"sich kaputtarbeiten\""}]'::jsonb, 'Ees geeds an zwitschan und I dawiag mi do!'),
  ('ees-geeds-an-zwitschan-und-i-dawiag-mi-do', 'Ees geeds an zwitschan und I dawiag mi do!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Ihr geht einen zwitschern, und ich derwürg'' mich da!', '[{"kategorie": "wörtlich", "text": "\"Ihr geht einen heben, und ich schufte mich hier zu Tode!\"  2. \"Ihr geht einen trinken, und ich arbeite mich hier kaputt!\"  3. Ihr kippt euch einen hinter die Binde, während ich mich hier zu Tode schufte!"}]'::jsonb, 'si dawiang'),
  ('dea-dawiagd-si-ins-schneiztiachl', 'Dea dawiagd si ins Schneiztiachl!', '', '', '', 'Echte Wiener Schmähperlen', 'Der derwürgt sich ins Schnäuztuch!', '[{"kategorie": "wörtlich", "text": "\"Der wichst sich einen ins Schnäuztuch!\"  2. \"Der schrubbelt sich einen in die Serviette!\"  3. \"Das ist ein Gewohnheitswichser mit dauerfeuchtem Schnäuztuch!\""}]'::jsonb, ''),
  ('hoi-a-poa-tschik-i-woat-dawaeu-im-auto', 'Hoi a poa Tschik - I woat dawäu im Auto!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Hol ein paar Tschick - ich warte derweil im Auto!', '[{"kategorie": "wörtlich", "text": "\"Hol ein paar Zigaretten - ich warte inzwischen im Auto!\"  2. Besorg ein paar Zigaretten – ich warte in der Zwischenzeit im Wagen!  3. Könntest du ein paar Zigaretten holen? Ich warte so lange im Auto!"}]'::jsonb, ''),
  ('dawaeu-si-eam-heandln-aufsetzd-saufd-ea-si-beim-wiatn-an-rausch-au', 'Dawäu si eam Heandln aufsetzd, saufd ea si beim Wiatn an Rausch au!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Derweil sie ihm Hörner aufsetzt, sauft er sich beim Wirten einen Rausch an!', '[{"kategorie": "wörtlich", "text": "\"Während sie ihm Hörner aufsetzt, betäubt er sich beim Wirten mit Alkohol!\"  2. \"In der Zeit, wo sie ihn betrügt, säuft er sich beim Wirten die Birne weg!\"  3. Während sie fremdgeht, ertränkt er beim Wirten seine Sorgen in Alkohol!"}]'::jsonb, ''),
  ('i-hob-glaubd-dea-daschiassd-mi-dawaeu-hoda-auf-habschi-tau', 'I hob glaubd, dea daschiassd mi, dawäu hoda auf Habschi tau!', '', '', '', 'Wiener Gaunersprache', 'Ich hab geglaubt, der derschießt mich - dabei hat er auf ''Habschi'' getan!', '[{"kategorie": "wörtlich", "text": "\"Ich dachte, der ballert mich weg – dabei hat er plötzlich auf Freund mit Friedensmission gemacht!\"  2. Ich dachte schon, ich krieg gleich Blei in die Fresse – doch dann kommt er auf Best-Buddy mit Kuss auf die Stirn!  3. Ich gab geglaubt, der knallt mich ab – und auf einmal spielt er den Biedrmann mit Friedensangebot!"}]'::jsonb, ''),
  ('i-gee-aufs-heisl-brennds-ees-derawaeu-de-zech', 'I gee aufs Heisl - brennds ees derawäu de Zech!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Ich geh aufs Häusel - brennt ihr derweil die Zeche!', '[{"kategorie": "wörtlich", "text": "\"Ich geh aufs Klo - zahlt ihr inwzischen die Zeche!\"  2. Ich geh mal kurz auf die Toilette – begleicht ihr in der Zwischenzeit mal die Zeche!  3. Ich muss mal kurz austreten - in der Zeit könnt ihr derweil die Rechnung zahlen!"}]'::jsonb, ''),
  ('derawaeu-da-gooli-min-schiri-noo-dischkutiad-haud-eam-da-neina-de-kuugl-eine', 'Derawäu da Gooli min Schiri noo dischkutiad, haud eam da Neina de Kuugl eine!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Derweil der Goalie mit''m Schiri noch diskutiert, haut ihm der Neuner die Kugel rein!', '[{"kategorie": "wörtlich", "text": "\"Während der Tormann mit dem Schiedsrichter noch diskutiert, zimmert ihm der Mittelstürmer den Ball rein!\"  2. Während der Keeper sich noch mit dem Unparteiischen streitet, zimmert ihm der Stürmer den Ball ins Netz!  3. In dem Moment, wo der Torwart noch mit dem Schiedsrichter diskutiert, drückt ihm der Neuner den Ball ganz locker rein!"}]'::jsonb, ''),
  ('ea-hod-glaubd-ea-leegds-heit-floch-derawaeu-hod-si-sein-bestn-habschi-oogschleppd', 'Ea hod glaubd, ea leegds heit floch - derawäu hod si sein bestn Habschi oogschleppd!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Er hat geglaubt, er legt sie heute flach - derweil hat sie seinen besten Habschi abgeschleppt!', '[{"kategorie": "wörtlich", "text": "\"Er dachte, er legt sie heute flach - derweil hat sie seinen besten Kumpel abgeschleppt!\"  2. Er hat geglaubt, er landet heute bei ihr – stattdessen ist sie mit seinem besten Freund abgedampft!  3. Er war sich sicher, er kriegt sie heute rum - doch dann ist sie mit seinem Top-Kumpel abgerauscht!"}]'::jsonb, ''),
  ('oid-owa-ohoo', 'Oid, owa ohoo!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Alt, aber oho!', '[{"kategorie": "wörtlich", "text": "\"Alt, aber scharf!\"  2. \"Nicht ganz taufrisch, aber immer noch ein Kracher!\"  3. \"Alt? Vielleicht. Aber geiler denn je!\""}]'::jsonb, ''),
