  ('dea-haengd-voi-drin', 'Dea hängd voi drin!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der hängt voll drin!', '[{"kategorie": "wörtlich", "text": "\"Der steckt da voll drin!\"  2. \"Der ist da richtig in was reingeraten!\"  3. \"Der steckt bis zum Hals in der Scheiße!\"  4. \"Der steckt bis über beide Ohren im Schlamassel!\""}]'::jsonb, ''),
  ('dea-sitzt-gaunz-schee-drin', 'Dea sitzt gaunz schee drin!', '', '', '', 'Wiener Gaunersprache', 'Der sitzt ganz schön drin!', '[{"kategorie": "wörtlich", "text": "\"Der sitzt ganz schön in der Falle!\"  2. \"Der ist da richtig in was reingeraten!\"  3. \"Der sitzt ganz tief in der Scheiße!\"  4. \"Der steckt bis über beide Ohren im Schlamassel!\""}]'::jsonb, ''),
  ('a-wuchtl-druckn', 'a Wuchtl druckn', '', '', '', '', 'eine Wuchtel drücken', '[{"kategorie": "", "text": "einen pointierten Scherz reißen"}, {"kategorie": "", "text": "schwindeln, anschwindeln (und dabei die Lüge homorvoll verpacken)"}]'::jsonb, ''),
  ('dea-hod-ma-scho-wiida-a-wuchtl-druckn-woin', 'Dea hod ma scho wiida a Wuchtl druckn woin!', '', '', '', '', 'Der wollte mir schon wieder eine Wuchtel drucken!', '[{"kategorie": "", "text": "Der wollte mir schon wieder eine Lüge auftischen!  2. Der wollte mir schon wieder etwas vorgaukeln!"}]'::jsonb, ''),
