  ('des-bauxal-tippld-neem-da-muata-dahea-wiara-pinguin', 'Des Bauxal tippld neem da Muata dahea wiara Pinguin!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Das Bauxerl tippelt neben der Mutter einher wie ein Pinguin!', '[{"kategorie": "wörtlich", "text": "\"Das Kleinkind wackelt neben der Mutter hin und her wie ein Pinguin!\"  2. Das Kind tapselt wacklig neben der Mutter wie ein kleiner Pinguin!  3. Das Kleinkind watschelt neben der Mutter wie ein Mini-Pinguin!"}]'::jsonb, ''),
  ('i-hob-de-hoitarung-foisch-diiwaed-jetzt-haengd-ollas-schiif', 'I hob de Hoitarung foisch diiwäd - jetzt hängd ollas schiif!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Ich hab die Halterung falsch gedübelt – jetzt hängt alles schief!', '[{"kategorie": "wörtlich", "text": "\"Ich habe die Halterung nicht richtig befestigt – deshalb hängt das Ding jetzt schief!\"  2. Ich hab voll danebengedübelt – jetzt hängt das Ding windschief!  3. Ich hab die Halterung falsch montiert – jetzt ist alles aus dem Lot!"}]'::jsonb, ''),
  ('a-hiadl-diiwaen', 'a Hiadl diiwän', '', '', '', 'Wiener Sprüche, die sitzen!', 'ein Hütchen dübeln', '[{"kategorie": "wörtlich", "text": "\"sich ein Tütchen reinziehen\""}, {"kategorie": "", "text": "einen Joint kiffen"}, {"kategorie": "", "text": "einen Tütenkopf wegrauchen"}]'::jsonb, 'Si diiwäd a Hiadl nochn aundan und red dabei min Eiskostn!'),
  ('si-diiwaed-a-hiadl-nochn-aundan-und-red-dabei-min-eiskostn', 'Si diiwäd a Hiadl nochn aundan und red dabei min Eiskostn!', '', '', '', 'Echte Wiener Schmähperlen', 'Sie dübelt ein Hütchen nach dem anderen und redet dabei mit ihrem Eiskasten!', '[{"kategorie": "wörtlich", "text": "\"Sie zieht sich einen Joint nach dem anderen rein und redet dabei mit ihrem Kühlschrank!\"  2. Sie ballert einen Joint nach dem anderen weg und philosophiert mit dem Kühlschrank!  3. Sie knallt sich die Tüten rein, als gäb’s kein Morgen – und ihr Kühlschrank ist ihr Therapeut!"}]'::jsonb, ''),
  ('si-diiwaed-aan-gschbritztn-nochn-aundan', 'Si diiwäd aan Gschbritztn nochn aundan!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Sie dübelt einen Gspritzten nach dem anderen!', '[{"kategorie": "wörtlich", "text": "\"Sie kippt sich einen [[Gespritzten]] nach dem anderen hinter die Binde!\"  2. Sie schüttet sich einen Gespritzten nach dem anderen rein!  3. Sie pfeift die Gespritzten weg wie Wasser!"}]'::jsonb, ''),
  ('maunche-diiwaen-duachs-leebm-ois-gaebs-ka-muang', 'Maunche diiwän duachs Leebm, ois gäbs ka muang!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Manche dübeln durchs Leben, als gäbe es kein Morgen!', '[{"kategorie": "wörtlich", "text": "\"Manche brettern durchs Leben, als gäbe es kein Morgen!\"  2. Manche rasen durchs Leben, als stünde die Welt in Flammen!  3. Manche jagen durchs Leben, als wäre die Zeit ihr größter Feind!"}]'::jsonb, ''),
  ('si-haum-eam-diiwaed-bis-a-nimma-aufgschdaundn-is', 'Si haum eam diiwäd, bis a nimma aufgschdaundn is!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Sie haben ihn gedübelt, bis er nicht mehr aufgestanden ist!', '[{"kategorie": "wörtlich", "text": "\"Sie haben ihn geprügelt, bis er nicht mehr aufgestanden ist!\"  2. Sie haben ihn windelweich geprügelt, bis er icht mehr aufstehen konnte!  3. Sie haben ihn zu Boden geprügelt – und nicht wieder hochkommen lassen!"}]'::jsonb, ''),
  ('ea-diiwaed-wiara-beaseaka', 'Ea diiwäd wiara Beaseaka!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Er rackert wie ein Berserker!', '[{"kategorie": "wörtlich", "text": "\"Er schuftet wie ein Besessener!\"  2. Er ackert wie ein Ochse!  3. Er [[barabert]], als gäbe es kein Morgen!"}]'::jsonb, ''),
  ('a-echta-diiwaebaam-biagd-si-ned', 'A echta Diiwäbaam biagd si ned!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Ein echter Dübelbaum biegt sich nicht!', '[{"kategorie": "wörtlich", "text": "\"Ein Dübelbaum gibt nicht nach!\"  2. Der Dübelbaum steht da, als hätt er die Statik erfunden!  3. Ein echter Dübelbaum bricht nicht – auch wenn’s kracht im Gebälk!"}]'::jsonb, ''),
  ('si-duckn', 'si duckn', '', '', '', '', 'sich ducken', '[{"kategorie": "", "text": "Kopf und Schultern einziehen"}, {"kategorie": "", "text": "Oberkörper beugen"}, {"kategorie": "", "text": "in die Knie gehen, in die Hocke gehen"}]'::jsonb, ''),
  ('dicke-dudl', 'dicke Dudl', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'dicke Dudel', '[{"kategorie": "wörtlich, Kurzform für", "text": "\"dicke Dudelsackquetsche\" (=\"aufgeblähter Blasebalg des Dudelsacks\", vom mittelhochdeutschen \"dudelsac\"=\"Dudelsack\")"}, {"kategorie": "scherzhaft für", "text": "sehr rundliche fröhliche Frau, pfundige Jodelfee, \"rollende Lachwalze\", \"wamperte Sackpfeifn\""}]'::jsonb, ''),
