  ('dullioeoe-substantiv', 'Dulliöö [Substantiv]', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Dulliöh', '[{"kategorie": "wörtlich", "text": "\"Jodeljauchzer\" (\"beim Jodeln ausgestoßener Jauchzer\" - lautmalerisches Wort, welches das jauchzende Tönen eines Dudelsacks nachahmt, vom mittelhochdeutschen \"dudelsac\"=\"Dudelsack\")"}, {"kategorie": "allg.", "text": "Schwips, leichter Rausch, Zustand fröhlicher Berauschung, \"Jodelrausch\""}]'::jsonb, ''),
