  ('aum-schdaund-duachdraan', 'aum Schdaund duachdraan', '', '', '', '', 'am Stand durchdrehen', '[{"kategorie": "", "text": "wie aus heiterem Himmel einen Wutanfall bekommen"}, {"kategorie": "", "text": "von einem Moment auf den anderen explodieren, hochgehen"}, {"kategorie": "", "text": "plötzlich in Rage geraten"}]'::jsonb, ''),
  ('si-ane-duachzaahn', 'si ane duachzaahn', '', '', '', '', 'sich eine durchziehen', '[{"kategorie": "", "text": "sich eine Zigarette genehmigen"}, {"kategorie": "", "text": "eine Zigarette genüsslich von Anfang bis Ende durchrauchen"}]'::jsonb, ''),
  ('im-dusl-sei', 'im Dusl sei', '', '', '', '', 'im Dusel sein', '[{"kategorie": "", "text": "leicht berauscht sein"}, {"kategorie": "", "text": "sich aufgrund von Alkohlkonsum im Halbschlaf befinden"}]'::jsonb, ''),
  ('dea-hiasl-is-aufn-aansaschmaeae-einegfoin', 'Dea Hiasl is aufn Aansaschmää einegfoin!', '', '', '', 'Wiener Gaunersprache', 'Der Hiasl ist auf den Einserschmäh reingefallen', '[{"kategorie": "wörtlich", "text": "\"Der Schwachkopf ist auf Trick 17 reingefallen!\"  2. Der [[Dillo]] ist prompt auf den ältesten Trick der Welt reingefallen!  3. Der Depp hat sich einwickeln lassen wie ein Pausenbrot!"}]'::jsonb, ''),
  ('des-geed-auf-kan-foi-eine', 'Des geed auf kan Foi eine!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das geht auf keinen Fall rein!', '[{"kategorie": "wörtlich", "text": "\"Das klappt auf keinen Fall!\"  2. Das funktioniert auf keinen Fall!  3. Das haut garantiert nicht hin!"}]'::jsonb, ''),
  ('waunnsd-duat-einegeesd-bist-im-oasch-oida', 'Waunnsd duat einegeesd, bist im Oasch, Oida!', '', '', '', 'Wiener Gaunersprache', 'Wenn du dort reingehst, bist du im Arsch, Alter!', '[{"kategorie": "wörtlich", "text": "\"Wenn du dort reingehst, bist du geliefert, Alter!\"  2. Wenn du dort reingehst, ist Schicht im Schacht, Bruder!  3. Wenn du dort reingehst, bist du erledigt, Alter!"}]'::jsonb, ''),
  ('tua-ned-so-einefetzn-oida-solaungsd-no-bei-da-mutti-untam-hochbett-schlofsd', 'Tua ned so einefetzn, Oida, solaungsd no bei da Mutti untam Hochbett schlofsd!', '', '', '', 'Wiener Gaunersprache', 'Tu nicht so reinfetzen, Alter, solange du noch bei Mutti unterm Hochbett schläfst!', '[{"kategorie": "wörtlich", "text": "\"Tu nicht so protzen, Alter, solange du noch bei Mutti unterm Hochbett schläfst!\"  2. Spiel nicht den Boss, Alter, solange Mama dir noch die Socken stopft!  3. Komm mal runter, du King im Kinderzimmer - und protz erst wieder, wenn du eine eigene Wohnung hast!"}]'::jsonb, ''),
  ('si-einehaengan', 'si einehängan', '', '', '', 'Grundwortschatz Wienerisch', 'sich einehängen', '[{"kategorie": "wörtlich", "text": "\"sich hineinhängen\" (Kompositum aus dem abtrennbaren Präfix [[eine]]=\"hinein\" und \"hängan\"=\"hängen\")"}, {"kategorie": "allg.", "text": "seine ganze Kraft (für etwas) aufbieten, sich anstrengen, sich ins Zeug legen"}]'::jsonb, 'Häng di eine, wos geed!'),
  ('haeng-di-eine-wos-geed', 'Häng di eine, wos geed!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Häng dich rein, was geht!', '[{"kategorie": "wörtlich", "text": "\"Streng dich an, so viel du kannst!\"  2. \"Gib alles, was du hast!\"  3. Leg dich so richtig ins Zeug!  4. Hol raus aus dir, was geht!"}]'::jsonb, 'si einehängan'),
  ('si-einihaengan', 'si einihängan', '', '', '', 'Grundwortschatz Wienerisch', 'sich einihängen', '[{"kategorie": "wörtlich", "text": "\"sich hineinhängen\" (Kompositum aus dem abtrennbaren Präfix [[eini]]=\"hinein\" und \"hängan\"=\"hängen\")"}, {"kategorie": "allg.", "text": "seine ganze Kraft (für etwas) aufbieten, sich anstrengen, sich ins Zeug legen"}]'::jsonb, 'Häng di eini, wos geed!'),
  ('haeng-di-eini-wos-geed', 'Häng di eini, wos geed!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Häng dich rein, was geht!', '[{"kategorie": "wörtlich", "text": "\"Streng dich an, so viel du kannst!\"  2. \"Gib alles, was du hast!\"  3. Leg dich so richtig ins Zeug!"}]'::jsonb, 'si einihängan'),
  ('in-fuenf-minutn-jankad-si-dea-a-komplette-pizza-eine', 'In fünf Minutn jankad si dea a komplette Pizza eine!', '', '', '', 'Wiener Sprüche, die sitzen!', 'In fünf Minuten jankert sich der eine komplette Pizza rein!', '[{"kategorie": "wörtlich", "text": "\"In fünf Minuten jagt sich der eine komplette Pizza rein!\"  2. In null Komma nix hat der eine ganze Pizza weggeputzt!  3. Der braucht nicht mehr als fünf Minuten, um sich eine komplette Pizza reinzustopfen!"}]'::jsonb, ''),
  ('de-kinda-haum-d-hendln-mit-vueue-gschraa-in-schdoi-einegjankad', 'De Kinda haum d''Hendln mit vüü Gschraa in Schdoi einegjankad!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Die Kinder haben die Hühner mit viel Geschrei in den Stall reingejankert!', '[{"kategorie": "wörtlich", "text": "\"Die Kinder haben die Hühner mit viel Geschrei in den Stall reingejagt!\"  2. Die Kinder haben die Hühner mit viel Gekreisch in den Stall getrieben!  3. Die Kids haben die Hühner mit viel Gekreisch in den Stall gescheucht!"}]'::jsonb, ''),
  ('in-wos-fiaran-schaas-host-mi-do-wiida-einegjankad', 'In wos fiaran Schaas host mi do wiida einegjankad?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'In was für einen Schas hast du mich da wieder reingejankert?', '[{"kategorie": "wörtlich", "text": "\"In was für einen Blödsinn hast du mich da wieder reingeritten?\"  2. In welchen Scheiß hast du mich da wieder reinmanövriert?  3. Was ist das schon wieder für ein Dreck, den du mir da eingebrockt hast?"}]'::jsonb, ''),
  ('da-oazd-hod-ma-s-jaukal-oone-a-wuat-afoch-einegjankad', 'Da Oazd hod ma s''Jaukal oone a Wuat afoch einegjankad!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Der Arzt hat mir das Jaukerl ohne ein Wort einfach reingejankert!', '[{"kategorie": "wörtlich", "text": "\"Der Arzt hat mir die Spritze ohne Vorwarnung einfach reingejagt!\"  2. Der Arzt hat mir die Spritze einfach ohne ein Wort reingehauen!  3. Der Arzt hat mir die Spritze reingejagt, ohne mir vorher ein Wort zu sagen!"}]'::jsonb, ''),
  ('dea-kraeud-in-schaeaef-von-hint-eine-dass-scho-peinlich-is', 'Dea kräud in Schääf von hint eine, dass scho peinlich is!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der kräult dem Chef von hinten rein, dass es schon peinlich ist!', '[{"kategorie": "wörtlich", "text": "\"Der kriecht dem Chef von hinten rein, dass es schon peinlich ist!\"  2. Der kriecht dem Chef so tief in den Arsch, dass man schon rot wird beim Zusehen!  3. Er biedert sich beim Chef so extrem an, dass es echt schon unangenehm ist!"}]'::jsonb, 'wem von hint einekräun'),
  ('wem-von-hint-einekraeun', 'wem von hint einekräun', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem von hinten reinkräulen', '[{"kategorie": "wörtlich", "text": "\"jemandem in den Arsch kriechen\""}, {"kategorie": "", "text": "sich bei jemandem einschleimen"}, {"kategorie": "", "text": "[[wem in Oasch kräun]]"}, {"kategorie": "", "text": "[[wem de Eia schaukln]]"}]'::jsonb, ''),
  ('si-wos-einelaan', 'si wos einelaan', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'sich was reinleeren', '[{"kategorie": "wörtlich", "text": "\"sich ordentlich was reinschütten\""}, {"kategorie": "", "text": "sich gehörig was reingießen"}, {"kategorie": "", "text": "sich ordentlich abfüllen"}]'::jsonb, 'Dea laad si an eine!'),
  ('dea-laad-si-an-eine', 'Dea laad si an eine!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Der leert sich einen rein!', '[{"kategorie": "wörtlich", "text": "\"Der schüttet sich ordentlich was rein!\"  2. Der gießt sich ordentlich einen rein!  3. Der füllt sich richtig ab!"}]'::jsonb, 'si wos einelaan'),
  ('dea-hod-mi-einelossn-oone-dass-i-wos-bemeakd-haedad', 'Dea hod mi einelossn, oone dass I wos bemeakd hädad!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der hat mich reingelassen, ohne dass ich was bemerkt hätte!', '[{"kategorie": "wörtlich", "text": "\"Der hat mich reingelassen, ohne dass ich was bemerkt hätte!\"  2. Der hat mich voll reingeritten, ohne dass ich’s gecheckt hab!  3. Der hat mich übers Ohr gehauen, ohne dass ich irgendetwas geschnallt hätte!"}]'::jsonb, ''),
